package com.bibliotech.book.controller; import com.bibliotech.book.entity.Book; import com.bibliotech.book.service.BookService; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/books") public class BookController{private final BookService s;public BookController(BookService x){s=x;}@GetMapping public List<Book> all(){return s.all();}@GetMapping("/{id}")public Book get(@PathVariable Long id){return s.get(id);}@PostMapping public ResponseEntity<Book> add(@RequestBody Book b){return ResponseEntity.status(201).body(s.save(b));}@PutMapping("/{id}") public Book update(@PathVariable Long id,@RequestBody Book b){return s.update(id,b);}@DeleteMapping("/{id}")public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}@PostMapping("/{id}/availability")public Book availability(@PathVariable Long id,@RequestParam int change){return s.change(id,change);}}
